require '../config.php';require '../auth.php';require '../helpers.php';require_admin();$id=(int)($_GET['id']??$_POST['id']??0);$stmt=$conn->prepare('SELECT * FROM facilities WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();$f=$stmt->get_result()->fetch_assoc();if(!$f){http_response_code(404);die('Facility not found.');}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['facility_name']??'');$description=trim($_POST['description']??'');$location=trim($_POST['location']??'');$price=(float)($_POST['price_per_hour']??-1);$active=isset($_POST['is_active'])?1:0;[$newImage,$uploadError]=handle_image_upload($_FILES['image']??null,__DIR__.'/../uploads','facility');if($uploadError)$error=$uploadError;elseif($name===''||$description===''||$location===''||$price<0)$error='Complete every field with a valid fee.';else{$image=$newImage?:$f['image_url'];$stmt=$conn->prepare('UPDATE facilities SET facility_name=?,description=?,location=?,price_per_hour=?,image_url=?,is_active=? WHERE id=?');$stmt->bind_param('sssdsii',$name,$description,$location,$price,$image,$active,$id);$stmt->execute();if($newImage)delete_image_file($f['image_url'],__DIR__.'/../uploads');header('Location: facilities.php');exit;}}$pageTitle='Edit Facility';require 'partials/header.php';?>
<div class="form-card"><h1>Edit Facility</h1><?php if($error):?><p class="alert alert-error"><?=htmlspecialchars($error)?></p><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="id" value="<?=$id?>"><label>Name <input name="facility_name" value="<?=htmlspecialchars($f['facility_name'])?>" required></label><label>Description <textarea name="description" rows="4" required><?=htmlspecialchars($f['description'])?></textarea></label><label>Location <input name="location" value="<?=htmlspecialchars($f['location'])?>" required></label><label>Fee/hour (RM) <input type="number" name="price_per_hour" min="0" step="0.01" value="<?=htmlspecialchars($f['price_per_hour'])?>" required></label><label>New photo <input type="file" name="image" accept="image/*"></label><label><input type="checkbox" name="is_active" <?=$f['is_active']?'checked':''?>> Active</label><button>Save Changes</button></form></div><?php require 'partials/footer.php';?>

